// §3.3 渠道作战台只读运维聚合。全部只读。
// 口径：渠道性能/成功率/错误以 request_attempts（attempt 粒度，每次尝试命中一条渠道）为准；
// TPS/token 因无 per-attempt usage，按 request_records.final_channel_id 归因（最终成功渠道）。
// Channel 缓存画像额外排除请求开始已有 Sticky 绑定、但最终成功落到其他 Channel 的整条 usage。
// 区间 [from,to) 半开；narg 可空（NULL 不过滤）。延迟由 completed_at-started_at 推导（毫秒）。
// ChannelsOpsTable 渠道运维主表（分页）：每渠道 attempt 指标 + 绑定模型数 + 最近错误，默认最需处理优先。
func (q *Queries) ChannelsOpsTable(ctx context.Context, arg ChannelsOpsTableParams) ([]ChannelsOpsTableRow, error) {
	rows, err := q.db.Query(ctx, channelsOpsTable,
		arg.FromTime,
		arg.ToTime,
		arg.Status,
		arg.ProviderID,
		arg.Search,
		arg.SortField,
		arg.SortDesc,
		arg.PageOffset,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ChannelsOpsTableRow
	for rows.Next() {
		var i ChannelsOpsTableRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.Status,
			&i.Protocols,
			&i.AdapterKey,
			&i.Origin,
			&i.Priority,
			&i.ResponseTimeoutMs,
			&i.FirstTokenTimeoutMs,
			&i.Credential,
			&i.SupplyForm,
			&i.ConcurrencyLimit,
			&i.CreatedAt,
			&i.LastTestedAt,
			&i.LastTestOk,
			&i.LastTestLatencyMs,
			&i.LastTestError,
			&i.CredentialValid,
			&i.CostMultiplier,
			&i.CostMultiplierOverrides,
			&i.ProviderRechargeRate,
			&i.ProviderID,
			&i.ProviderName,
			&i.ProviderCurrency,
			&i.AttemptTotal,
			&i.AttemptSucceeded,
			&i.TimeoutTotal,
			&i.LatencySample,
			&i.LatencyAvg,
			&i.LatencyP50,
			&i.LatencyP90,
			&i.LatencyP95,
			&i.LatencyP99,
			&i.BoundModels,
			&i.RecentErrorCode,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

