const deleteChannelCascade = `-- name: DeleteChannelCascade :execrows
WITH deleted_channel_price_service_tiers AS (
    DELETE FROM channel_price_service_tiers
    WHERE channel_price_service_tiers.channel_price_id IN (
        SELECT channel_prices.id FROM channel_prices WHERE channel_prices.channel_id = $1
    )
),
deleted_channel_prices AS (
    DELETE FROM channel_prices WHERE channel_prices.channel_id = $1
),
deleted_channel_models AS (
    DELETE FROM channel_models WHERE channel_models.channel_id = $1
),
deleted_channel_cost_multipliers AS (
    DELETE FROM channel_cost_multipliers WHERE channel_cost_multipliers.channel_id = $1
),
deleted_channel_model_verification_items AS (
    DELETE FROM channel_model_verification_items
    WHERE channel_model_verification_items.run_id IN (
        SELECT channel_model_verification_runs.id
        FROM channel_model_verification_runs
        WHERE channel_model_verification_runs.channel_id = $1
    )
),
deleted_channel_model_verification_runs AS (
    DELETE FROM channel_model_verification_runs
    WHERE channel_model_verification_runs.channel_id = $1
),
deleted_provider_probe_records AS (
    DELETE FROM provider_probe_records WHERE provider_probe_records.channel_id = $1
),
deleted_subscription_ledger AS (
    DELETE FROM subscription_ledger_entries
    WHERE subscription_ledger_entries.account_id IN (
        SELECT subscription_accounts.id FROM subscription_accounts
        WHERE subscription_accounts.channel_id = $1
    )
),
deleted_subscription_accounts AS (
    DELETE FROM subscription_accounts WHERE subscription_accounts.channel_id = $1
),
deleted_runtime_control_operations AS (
    DELETE FROM runtime_control_operations WHERE runtime_control_operations.channel_id = $1
)
DELETE FROM channels WHERE channels.id = $1
`

// DeleteChannelCascade 物理删除 channel，用于清理录错且从未使用的脏数据，并在同一条语句内
// 级联清理 channel 自身的全部配置子表：channel_models（模型绑定）、channel_prices（渠道-模型价，
// 绝对成本覆盖）及其 Fast 档子行（channel_price_service_tiers）、channel_cost_multipliers（价格倍率，DEC-027）。
// 充值汇率归属服务商（provider_recharge_rates），不随渠道删除。
// 这些都是「渠道自身配置」（无请求/账务事实），随渠道硬删一并清理；channel_test_logs 与
// channel_model_discovery 的 runs/items 走 ON DELETE CASCADE 自动清。
// channel_model_verification 的 items 必须在删 provider_probe_records 之前显式删除：
// items.probe_id → probe_records 是 NO ACTION 外键，其约束触发器按入队顺序先于 channels 的
// CASCADE（runs → items）执行，只靠级联会在语句末误报 23503「探测仍被验证明细引用」。
// provider_probe_records（探测事实）的 channel_id 非空，随渠道一并删除；若某条探测已产生
// provider 账务（provider_ledger_entries 引用 probe_record_id/channel_id），语句报 23503 回滚，
// 探测花过钱即属账务历史，本就该挡。
// 外键均为默认 NO ACTION（约束在语句末校验），故 CTE 删子表 + 删主体在单条语句内原子完成：
// 子配置先删除，语句末 channels 的删除不会留下悬挂引用。若 channel 仍被请求/账务历史
// （request_attempts/request_records/cost_snapshots/settlement_recovery_jobs）引用，
// 整条语句报 23503 全部回滚，上层降级为 conflict，提示改用停用/保持归档。返回值为 channels 行的受影响数（0 表示 channel 不存在）。
// 池型渠道的订阅账号及其台账是「渠道自身供给配置」：账号从未服务过请求时随渠道一并清理；
// 一旦有请求历史（request_records.final_account_id NO ACTION），语句报 23503 整体回滚，
// 与渠道自身的历史引用同一兜底（上层降级 conflict，提示保持归档）。
// 两阶段发布的运维审计行（channel_capacity 操作）随渠道清理：
// 它是运行态控制的内部审计，不是请求/账务事实，硬删渠道时保留无意义且会挡删除（23503）。
func (q *Queries) DeleteChannelCascade(ctx context.Context, id int64) (int64, error) {
	result, err := q.db.Exec(ctx, deleteChannelCascade, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const deleteChannelModel = `-- name: DeleteChannelModel :execrows
WITH deleted_channel_prices AS (
    DELETE FROM channel_prices
    WHERE channel_prices.channel_id = $1
      AND channel_prices.model_id = $2
)
DELETE FROM channel_models
WHERE channel_models.channel_id = $1
  AND channel_models.model_id = $2
`

type DeleteChannelModelParams struct {
	ChannelID int64
	ModelID   int64
}

// DeleteChannelModel 删除绑定，并在同一条语句内级联清理该 (channel_id, model_id) 边自身的
// channel_prices（渠道-模型成本价，追加式配置、无删除接口，只能停用）——否则只要该边配过成本价，
// 就会被自身配置行永久挡住解绑。channel_prices 仅被账务历史（cost_snapshots/price_snapshots/
// settlement_recovery_jobs）以 NO ACTION 外键引用：若该边确有计费历史，删 channel_prices 触发
// 23503 使整条语句回滚，上层降级为 conflict，提示改用停用——保住计费/审计链路。
// 无历史时（仅配置行）则干净解绑。返回值为 channel_models 行的受影响数（0 表示绑定不存在）。
func (q *Queries) DeleteChannelModel(ctx context.Context, arg DeleteChannelModelParams) (int64, error) {
	result, err := q.db.Exec(ctx, deleteChannelModel, arg.ChannelID, arg.ModelID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

