const listChannelCostMultipliersByChannel = `-- name: ListChannelCostMultipliersByChannel :many
SELECT
    ccm.id,
    ccm.channel_id,
    ccm.model_id,
    ccm.multiplier,
    ccm.status,
    ccm.effective_from,
    ccm.effective_to,
    ccm.created_at,
    ccm.updated_at,
    m.model_id AS model_external_id,
    m.display_name AS model_display_name,
    m.status AS model_status
FROM channel_cost_multipliers ccm
LEFT JOIN models m ON m.id = ccm.model_id
WHERE ccm.channel_id = $1
ORDER BY (ccm.model_id IS NULL) DESC, ccm.model_id, ccm.effective_from DESC, ccm.id DESC
`

