const prepareChannelCredentialRotation = `-- name: PrepareChannelCredentialRotation :one
WITH current AS MATERIALIZED (
    SELECT c.id, c.credential AS previous_credential, c.credential_valid AS previous_credential_valid
    FROM channels AS c
    WHERE c.id = $1
    FOR UPDATE
), updated AS (
    UPDATE channels AS c
    SET credential = $2,
        credential_valid = CASE
            WHEN current.previous_credential IS DISTINCT FROM $2 THEN FALSE
            ELSE c.credential_valid
        END,
        last_tested_at = CASE
            WHEN current.previous_credential IS DISTINCT FROM $2 THEN NULL
            ELSE c.last_tested_at
        END,
        last_test_ok = CASE
            WHEN current.previous_credential IS DISTINCT FROM $2 THEN NULL
            ELSE c.last_test_ok
        END,
        last_test_latency_ms = CASE
            WHEN current.previous_credential IS DISTINCT FROM $2 THEN NULL
            ELSE c.last_test_latency_ms
        END,
        last_test_error = CASE
            WHEN current.previous_credential IS DISTINCT FROM $2 THEN NULL
            ELSE c.last_test_error
        END,
        config_revision = c.config_revision + CASE
            WHEN current.previous_credential IS DISTINCT FROM $2 THEN 1
            ELSE 0
        END,
        updated_at = CASE
            WHEN current.previous_credential IS DISTINCT FROM $2 THEN now()
            ELSE c.updated_at
        END
    FROM current
    WHERE c.id = current.id
    RETURNING
        c.id AS channel_id,
        c.provider_id,
        c.protocols,
        c.adapter_key,
        c.credential,
        c.credential_valid,
        c.config_revision,
        (current.previous_credential IS DISTINCT FROM $2)::boolean AS credential_changed
)
SELECT
    updated.channel_id,
    updated.provider_id,
    updated.protocols,
    updated.adapter_key,
    updated.credential,
    updated.credential_valid,
    updated.config_revision,
    updated.credential_changed,
    p.slug AS provider_slug,
    p.origin,
    p.origin_revision,
    p.status_revision,
    cpx2.url AS channel_proxy_url
FROM updated
JOIN providers p ON p.id = updated.provider_id
LEFT JOIN channels ch2 ON ch2.id = updated.channel_id
LEFT JOIN proxies cpx2 ON cpx2.id = ch2.proxy_id AND cpx2.status = 'enabled'
`

type PrepareChannelCredentialRotationParams struct {
	ChannelID  int64
	Credential string
}

type PrepareChannelCredentialRotationRow struct {
	ChannelID         int64
	ProviderID        int64
	Protocols         []string
	AdapterKey        string
	Credential        string
	CredentialValid   bool
	ConfigRevision    int64
	CredentialChanged bool
	ProviderSlug      string
	Origin            string
	OriginRevision    int64
	StatusRevision    int64
	ChannelProxyUrl   pgtype.Text
}

// PrepareChannelCredentialRotation 原子判定同值/真变化并保存 credential。真变化只推进一次 config_revision，
// 同时先把 credential_valid 置 false、清空只属于旧 credential 的最近检测摘要；随后即时检测按返回的三类 revision 做 CAS。
func (q *Queries) PrepareChannelCredentialRotation(ctx context.Context, arg PrepareChannelCredentialRotationParams) (PrepareChannelCredentialRotationRow, error) {
	row := q.db.QueryRow(ctx, prepareChannelCredentialRotation, arg.ChannelID, arg.Credential)
	var i PrepareChannelCredentialRotationRow
	err := row.Scan(
		&i.ChannelID,
		&i.ProviderID,
		&i.Protocols,
		&i.AdapterKey,
		&i.Credential,
		&i.CredentialValid,
		&i.ConfigRevision,
		&i.CredentialChanged,
		&i.ProviderSlug,
		&i.Origin,
		&i.OriginRevision,
		&i.StatusRevision,
		&i.ChannelProxyUrl,
	)
	return i, err
}

const restoreChannel = `-- name: RestoreChannel :execrows
UPDATE channels
SET status = 'disabled', archived_at = NULL,
    config_revision = config_revision + 1, updated_at = now()
WHERE id = $1 AND status = 'archived'
`

// RestoreChannel 取消归档渠道：archived → disabled（archived_at 清空）。名字保持归档时的后缀名
// （如需干净名由管理员手动改）。调用方需先保证所属 provider 非 archived（服务层护栏）。
func (q *Queries) RestoreChannel(ctx context.Context, id int64) (int64, error) {
	result, err := q.db.Exec(ctx, restoreChannel, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateChannel = `-- name: UpdateChannel :one
UPDATE channels
SET name = $1,
    status = $2,
    priority = $3,
    supports_openai_fast = $4,
    response_timeout_ms = $5,
    first_token_timeout_ms = $6,
    sticky_enabled = $7,
    sticky_ttl_ms = $8,
    proxy_id = $9,
    config_revision = config_revision + (
        CASE WHEN (
            status IS DISTINCT FROM $2
            OR supports_openai_fast IS DISTINCT FROM $4
            OR response_timeout_ms IS DISTINCT FROM $5
            OR first_token_timeout_ms IS DISTINCT FROM $6
            OR sticky_enabled IS DISTINCT FROM $7
            OR sticky_ttl_ms IS DISTINCT FROM $8
            OR proxy_id IS DISTINCT FROM $9
        ) THEN 1 ELSE 0 END
    ),
    updated_at = now()
WHERE id = $10
RETURNING id, provider_id, name, adapter_key, credential, config_revision, capacity_revision, status, priority, sticky_enabled, sticky_ttl_ms, response_timeout_ms, first_token_timeout_ms, created_at, updated_at, last_tested_at, last_test_ok, last_test_latency_ms, last_test_error, credential_valid, archived_at, concurrency_limit, supports_openai_fast, protocols, supply_form, account_default_concurrency, proxy_id
`

